695	    .option('--chunk-size <words>', 'Words per chunk (default: 800)', (value) => Number.parseInt(value, 10))
696	    .option('--extensions <list>', 'Comma-separated list of allowed file extensions', (value) =>
697	      value.split(',').map((ext) => ext.trim().toLowerCase())
698	    )
699	    .action((options: { input?: string; output?: string; chunkSize?: number; extensions?: string[] }) => {
