762	    });
763	
764	  try {
765	    await program.parseAsync(process.argv);
766	  } catch (error) {
767	    log.error('CLI execution failed.', {
768	      error: error instanceof Error ? error.message : String(error)
769	    });
770	    process.exit(1);
771	  }
772	}
