import fs from 'fs';
import os from 'os';
import path from 'path';
import { afterEach, describe, expect, it } from 'vitest';

import {
  generateReport,
  loadDataset,
  runEvaluations,
  writeReport,
  validateThresholds,
  evaluateThresholds
} from './index.js';

const tmpDirs = [];
afterEach(() => {
  while (tmpDirs.length) {
    fs.rmSync(tmpDirs.pop(), { recursive: true, force: true });
  }
});

const createTempDir = () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-eval-'));
  tmpDirs.push(dir);
  return dir;
};

describe('Evaluation harness', () => {
  it('loads outputs and references', () => {
    const dir = createTempDir();
    const outputsPath = path.join(dir, 'outputs.json');
    const referencesPath = path.join(dir, 'references.json');
    fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World'], null, 2));
    fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world'], null, 2));

    const dataset = loadDataset({ outputsPath, referencesPath });
    expect(dataset.outputs).toEqual(['Hello', 'World']);
    expect(dataset.references).toEqual(['hello', 'world']);
  });

  it('runs default evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const exact = evaluations.find((metric) => metric.id === 'exact_match');
    const toxicity = evaluations.find((metric) => metric.id === 'toxicity');

    expect(exact.score).toBeCloseTo(1, 4);
    expect(toxicity.score).toBe(1);
  });

  it('generates and writes report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });
});

file.content:
### `frai update`
Check npm for the latest `frai` release and print upgrade instructions.

---

## Using `frai-core` (SDK)

Install from npm:
```bash
pnpm add frai-core
```

`frai-core` exposes modular helpers that the CLI uses under the hood:
- `Questionnaire` – interactive question flows.
- `Documents` – generate checklists, model cards, and risk files.
- `Scanners` – static analysis for AI indicators.
- `Rag` – policy-grounded indexing utilities.
- `Eval` – baseline evaluation metrics and report writers.
- `Finetune` – governance templates, validation, and readiness scoring.
- `Config` & `Providers` – key management and LLM provider wiring.

Example: generate documentation programmatically.

```ts
import fs from 'fs/promises';
import inquirer from 'inquirer';
import { Documents, Questionnaire, Scanners } from 'frai-core';

const answers = await Questionnaire.runQuestionnaire({
  prompt: (questions) => inquirer.prompt(questions)
});

const { checklist, modelCard, riskFile } = Documents.generateDocuments({ answers });
const scan = Scanners.scanCodebase({ root: process.cwd() });
const aiContext = Documents.buildContextForAITips(answers);

await fs.writeFile('checklist.md', checklist);
await fs.writeFile('model_card.md', modelCard);
await fs.writeFile('risk_file.md', riskFile);
await fs.writeFile('scan-summary.json', JSON.stringify(scan, null, 2));
await fs.writeFile('ai-context.txt', aiContext);
```

Because `frai-core` is a regular ESM package, you can import only the modules you need and embed FRAI capabilities inside automation pipelines, CI jobs, or custom products.

---

## Local Development

Clone the repository and work from source:

input.new_string:
Because `frai-core` is a regular ESM package, you can import only the modules you need and embed FRAI capabilities inside automation pipelines, CI jobs, or custom products.

### Eval with Thresholds

Use thresholds to gate CI jobs on evaluation metrics:

```ts
import { Eval } from 'frai-core';

const dataset = Eval.loadDataset({
  outputsPath: './outputs.json',
  referencesPath: './references.json'
});

const evaluations = Eval.runEvaluations({
  outputs: dataset.outputs,
  references: dataset.references
});

const thresholds = { exact_match: 0.9, toxicity: 0.95 };

// Validate thresholds
const validation = Eval.validateThresholds(thresholds, evaluations);
if (!validation.valid) {
  console.error('Validation failed:', validation.errors);
  process.exit(2);
}

// Generate report with thresholds
const report = Eval.generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds
});

// Write report
Eval.writeReport({ report, format: 'json', reportPath: 'eval-report.json' });

// Exit with appropriate code
if (report.passed === false) {
  process.exit(1); // At least one threshold failed
}
```

The report includes a `passed` field (true if all thresholds pass) and a `thresholds` array with individual pass/fail status for each metric.

---

