12	const defaultFs = fs;
13	
14	const ensureArray = (value) => (Array.isArray(value) ? value : []);
15	
16	export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
17	  if (!outputsPath) {
18	    throw new Error('outputsPath is required for evaluation.');
19	  }
20	
21	  const outputsAbsolute = path.resolve(outputsPath);
22	  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
23	  const outputs = JSON.parse(outputsRaw);
24	
25	  let references = [];
26	  let referencesAbsolute = null;
27	  if (referencesPath) {
28	    referencesAbsolute = path.resolve(referencesPath);
29	    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
30	    references = JSON.parse(referencesRaw);
31	  }
32	
33	  return {
34	    outputs,
35	    references,
36	    outputsPath: outputsAbsolute,
37	    referencesPath: referencesAbsolute
38	  };
39	}
40	
41	export function runEvaluations({
42	  outputs,
43	  references,
44	  metrics = DEFAULT_METRICS
45	} = {}) {
46	  const outs = ensureArray(outputs);
47	  const refs = ensureArray(references);
48	
49	  const evaluations = metrics.map((metric) => {
50	    if (typeof metric === 'function') {
51	      return metric(outs, refs);
52	    }
53	    if (metric && typeof metric.evaluate === 'function') {
54	      return metric.evaluate(outs, refs);
55	    }
56	    throw new Error('Invalid metric supplied to runEvaluations.');
57	  });
58	
59	  return evaluations;
60	}
61	
62	export function validateThresholds(thresholds = {}, evaluations = []) {
63	  const validMetricIds = new Set(evaluations.map((m) => m.id));
64	  const errors = [];
65	
66	  for (const [metricId, minValue] of Object.entries(thresholds)) {
67	    if (!validMetricIds.has(metricId)) {
68	      errors.push(
69	        `Unknown metric id: ${metricId}. Valid metric ids are: ${Array.from(validMetricIds).join(', ')}`
70	      );
71	    }
72	    if (typeof minValue !== 'number' || minValue < 0 || minValue > 1) {
73	      errors.push(`Invalid threshold for ${metricId}: must be a number between 0 and 1`);
74	    }
75	  }
76	
77	  return { valid: errors.length === 0, errors };
78	}
79	
80	export function evaluateThresholds(thresholds = {}, evaluations = []) {
81	  const thresholdsList = [];
82	  const metricMap = new Map(evaluations.map((m) => [m.id, m]));
83	
84	  for (const [metricId, min] of Object.entries(thresholds)) {
85	    const metric = metricMap.get(metricId);
86	    const score = metric?.score ?? null;
87	    const passed = score !== null && score >= min;
88	
89	    thresholdsList.push({
90	      metric: metricId,
91	      min,
92	      score,
93	      passed
94	    });
95	  }
96	
97	  return thresholdsList;
98	}
99	
100	export function generateReport({
101	  evaluations,
102	  outputsPath,
103	  referencesPath,
104	  generatedAt = new Date().toISOString(),
105	  thresholds
106	}) {
107	  const totalSamples = evaluations.reduce((total, metric) => {
108	    if (typeof metric.total === 'number') return Math.max(total, metric.total);
109	    return total;
110	  }, 0);
111	
112	  const report = {
113	    metadata: {
114	      generatedAt,
115	      outputsPath,
116	      referencesPath,
117	      totalSamples
118	    },
119	    metrics: evaluations
120	  };
121	
122	  if (thresholds && Object.keys(thresholds).length > 0) {
