import fs from 'fs';
import os from 'os';
import path from 'path';
import { describe, expect, it } from 'vitest';

import { generateReport, runEvaluations, validateThresholds, evaluateThresholds } from './index.js';

describe('Threshold functionality', () => {
  it('validates valid thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const result = validateThresholds({ exact_match: 0.5, toxicity: 0.8 }, evaluations);
    expect(result.valid).toBe(true);
    expect(result.errors).toEqual([]);
  });

  it('rejects unknown metrics', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const result = validateThresholds({ unknown_metric: 0.5 }, evaluations);
    expect(result.valid).toBe(false);
    expect(result.errors.some((e) => e.includes('Unknown metric id'))).toBe(true);
  });

  it('rejects out-of-range values', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const resultHigh = validateThresholds({ exact_match: 1.5 }, evaluations);
    expect(resultHigh.valid).toBe(false);

    const resultNegative = validateThresholds({ exact_match: -0.5 }, evaluations);
    expect(resultNegative.valid).toBe(false);

    const resultNaN = validateThresholds({ exact_match: 'abc' }, evaluations);
    expect(resultNaN.valid).toBe(false);
  });

  it('evaluates thresholds passing', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const thresholds = evaluateThresholds({ exact_match: 0.5, toxicity: 0.5 }, evaluations);
    expect(thresholds).toHaveLength(2);
    expect(thresholds.every((t) => t.passed)).toBe(true);
  });

  it('evaluates thresholds failing', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'DIFFERENT']
    });

    const thresholds = evaluateThresholds({ exact_match: 0.9 }, evaluations);
    expect(thresholds[0].passed).toBe(false);
  });

  it('fails thresholds when metric score is null', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: []
    });

    const thresholds = evaluateThresholds({ exact_match: 0.5 }, evaluations);
    expect(thresholds[0].score).toBe(null);
    expect(thresholds[0].passed).toBe(false);
  });

  it('reports passed=true when all thresholds pass', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5, toxicity: 0.5 }
    });

    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(2);
    expect(report.thresholds.every((t) => t.passed)).toBe(true);
  });

  it('reports passed=false when any threshold fails', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'DIFFERENT']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.9 }
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds[0].passed).toBe(false);
  });

  it('does not include passed/thresholds when no thresholds provided', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });

    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();
  });

  it('does not include passed/thresholds when empty thresholds provided', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {}
    });

    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();
  });

  it('includes correct metric data in thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const report = generateReport({
      evaluations,
