it('validates thresholds correctly', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello', 'World'],
    references: ['hello', 'world']
  });

  const validationPass = validateThresholds({ exact_match: 0.5 }, evaluations);
  expect(validationPass.valid).toBe(true);
  expect(validationPass.errors).toEqual([]);

  const validationUnknownMetric = validateThresholds({ unknown_metric: 0.5 }, evaluations);
  expect(validationUnknownMetric.valid).toBe(false);
  expect(validationUnknownMetric.errors.length).toBeGreaterThan(0);

  const validationInvalidValue = validateThresholds({ exact_match: 1.5 }, evaluations);
  expect(validationInvalidValue.valid).toBe(false);
});

it('evaluates thresholds in report', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello', 'World'],
    references: ['hello', 'WORLD']
  });

  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.5 }
  });

  expect(report.passed).toBe(true);
  expect(report.thresholds).toBeDefined();
  expect(report.thresholds).toHaveLength(1);
  expect(report.thresholds[0].metric).toBe('exact_match');
  expect(report.thresholds[0].passed).toBe(true);
});

it('fails thresholds when score is below minimum', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello', 'World'],
    references: ['hello', 'WORLD']
  });

  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.9 }
  });

  expect(report.passed).toBe(false);
  expect(report.thresholds[0].passed).toBe(false);
});

it('fails threshold when metric has no score', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: []
  });

  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.5 }
  });

  expect(report.passed).toBe(false);
  expect(report.thresholds[0].score).toBe(null);
  expect(report.thresholds[0].passed).toBe(false);
});

it('writes thresholds in markdown report', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });

  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.8 }
  });

  const dir = createTempDir();
  const mdPath = writeReport({
    report,
    format: 'markdown',
    reportPath: path.join(dir, 'report.md')
  });

  const content = fs.readFileSync(mdPath, 'utf8');
  expect(content).toContain('## Thresholds');
  expect(content).toContain('exact_match');
  expect(content).toContain('PASS');
});
